mapper.update:
UPDATE t_workflow_action_run SET assignee_id = #{row.assigneeId}, status = #{row.status}, output_json = #{row.outputJson},
        submitted_by = #{row.submittedBy}, submitted_time = #{row.submittedTime}, last_check_time = #{row.lastCheckTime},
        check_result = #{row.checkResult}, check_detail = #{row.checkDetail}, check_failure_count = IFNULL(#{row.checkFailureCount}, 0),
        last_check_success_time = #{row.lastCheckSuccessTime}, version = version + 1,
        update_time = #{row.updateTime}
        WHERE action_run_id = #{row.actionRunId} AND version = #{row.version}

mapper.select:
SELECT  FROM t_workflow_action_run
WHERE action_type = 'DATA_QUERY' AND status = 'PENDING' AND MOD(instance_id, #{shardTotal}) = #{shardIndex}
AND (last_check_time IS NULL OR last_check_time < #{checkedBefore})
ORDER BY last_check_time IS NOT NULL, last_check_time, action_run_id LIMIT #{limit}
